// The tajweed settings against the shared vectors every SDK 2.0.0 wrapper reproduces
// (test/tajweed/config_vectors.json + calibration_fixture.json, copied from the shared
// wrap/ folder, generated by settings_ref.py, revision 2: 39 cases each with a backend, 8 invalid
// app options). Every case's JSON exactly (numbers within 1e-9,
// dropped and refused identical), and every app_invalid case throws invalid_app_option.
// Run: npm test
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import {
  resolveSettings, parseRemote, TajweedSettings, TajweedSettingsError, validateCalibration, remoteBlockOf,
} from '../web/tajweed/settings.js';

const here = (p) => fileURLToPath(new URL(p, import.meta.url));
const vectors = JSON.parse(readFileSync(here('./tajweed/config_vectors.json'), 'utf8'));
const cal = JSON.parse(readFileSync(here('./tajweed/' + vectors.calibration), 'utf8'));

// Same keys, same values; numbers within 1e-9, everything else identical.
function same(got, want, at = '$') {
  if (typeof want === 'number') {
    assert.equal(typeof got, 'number', `${at}: ${JSON.stringify(got)} is not a number`);
    assert.ok(Math.abs(got - want) <= 1e-9, `${at}: ${got} != ${want}`);
    return;
  }
  if (want === null || typeof want !== 'object') { assert.equal(got, want, `${at}`); return; }
  if (Array.isArray(want)) {
    assert.ok(Array.isArray(got), `${at}: not an array`);
    assert.equal(got.length, want.length, `${at}: length ${got.length} != ${want.length} (${JSON.stringify(got)})`);
    want.forEach((w, i) => same(got[i], w, `${at}[${i}]`));
    return;
  }
  assert.ok(got && typeof got === 'object' && !Array.isArray(got), `${at}: not an object`);
  assert.deepEqual(Object.keys(got).sort(), Object.keys(want).sort(), `${at}: keys`);
  for (const k of Object.keys(want)) same(got[k], want[k], `${at}.${k}`);
}

test('vectors file is the one the contract describes', () => {
  assert.equal(vectors.format, 'quranlab.tajweed-settings-vectors/1');
  assert.ok(vectors.cases.length >= 39, `${vectors.cases.length} cases`);
  assert.ok(vectors.app_invalid.length >= 8);
  validateCalibration(cal);
});

for (const c of vectors.cases) {
  test(`resolve: ${c.name}`, () => {
    const got = resolveSettings(cal, c.remote, c.app, c.debug, c.backend);
    same(got, c.expect);
    // the dropped and refused lists exactly, order included
    assert.deepEqual(got.dropped, c.expect.dropped);
    assert.deepEqual(got.refused, c.expect.refused);
  });
}

for (const c of vectors.app_invalid) {
  test(`app invalid throws: ${c.name}`, () => {
    assert.throws(() => resolveSettings(cal, null, c.app, false),
      (e) => e instanceof TajweedSettingsError && e.code === c.expect_error);
    // the same through the stateful holder
    const s = new TajweedSettings(cal);
    assert.throws(() => s.setApp(c.app), (e) => e instanceof TajweedSettingsError && e.code === c.expect_error);
    assert.deepEqual(s.app, {}, 'a refused app option leaves the app layer unchanged');
  });
}

test('parseRemote never throws, whatever it is given', () => {
  const junk = [undefined, null, 0, 1, '', 'x', true, [], [1], {}, { v: 1, overrides: null }, { v: 1, checks: null },
    { v: 1, overrides: { cons_sub: null } }, { v: 1, overrides: { cons_sub: { threshold: NaN } } },
    { v: 1, overrides: { cons_sub: { threshold: Infinity } } }, { v: NaN }, { v: 1, preset: null, context: '' },
    Object.create(null)];
  for (const j of junk) {
    const r = parseRemote(j);
    assert.ok(Array.isArray(r.dropped));
    resolveSettings(cal, j, {}, false); // and resolving with it never throws either
  }
});

test('TajweedSettings: setters are the same as the app options, remote text tolerated', () => {
  const s = new TajweedSettings(cal);
  for (const c of vectors.cases) {
    s.clearApp();
    s.debug = c.debug;
    s.backend = c.backend;
    s.setRemote(c.remote === null ? null : JSON.stringify(c.remote));
    const a = c.app;
    if (a.preset) s.setPreset(a.preset);
    if (a.context) s.setContext(a.context);
    for (const [k, o] of Object.entries(a.overrides || {})) {
      if ('threshold' in o) s.setClassThreshold(k, o.threshold); else s.setClassPreset(k, o.preset);
    }
    for (const [k, b] of Object.entries(a.checks || {})) s.setCheck(k, b);
    same(s.effective(), c.expect, c.name);
  }
  // not JSON: the remote layer is cleared, nothing throws
  s.clearApp(); s.debug = false; s.backend = vectors.cases[0].backend;
  assert.deepEqual(s.setRemote('{not json'), ['remote']);
  same(s.effective(), vectors.cases[0].expect);
  // a whole /v1/config document carrying the block
  s.setRemote({ app: 'x', tajweed: { v: 1, preset: 'strict' } });
  assert.equal(s.effective().preset, 'strict');
  assert.deepEqual(remoteBlockOf({ tajweed: { v: 1 } }), { v: 1 });
  // invalid setter values throw and change nothing
  assert.throws(() => s.setClassThreshold('cons_sub', 21), TajweedSettingsError);
  assert.throws(() => s.setClassThreshold('cons_sub', NaN), TajweedSettingsError);
  assert.throws(() => s.setCheck('ghunna', true), TajweedSettingsError);
  assert.throws(() => s.setCheck('madd', 1), TajweedSettingsError);
  assert.throws(() => s.setContext('c16_l256'), TajweedSettingsError);
  assert.throws(() => s.clearClass('ghunna'), TajweedSettingsError);
  assert.throws(() => s.setClassThreshold('madd', 1), TajweedSettingsError); // features take a preset only
  assert.throws(() => { s.backend = 'fp16'; s.effective(); }, TajweedSettingsError);
  s.backend = 'int8';
  assert.deepEqual(s.app, {});
  // null removes an app setting so the lower layers show through
  s.setPreset('very_sensitive');
  assert.equal(s.effective().preset, 'very_sensitive');
  s.setPreset(null);
  assert.equal(s.effective().preset, 'strict');
});

test('calibration that cannot be used is refused', () => {
  const bad = JSON.parse(JSON.stringify(cal));
  bad.format = 'quranlab.tajweed-calibration/2';
  assert.throws(() => validateCalibration(bad), (e) => e.code === 'invalid_calibration' && e.field === 'format');
  const bad2 = JSON.parse(JSON.stringify(cal));
  bad2.contexts.c16_l64.sites.cons_sub.thresholds.balanced = '1.0';
  assert.throws(() => validateCalibration(bad2), (e) => e.code === 'invalid_calibration');
  // a missing preset threshold is allowed: it disables the class (the vectors check the effect)
  const ok = JSON.parse(JSON.stringify(cal));
  delete ok.contexts.c16_l64.sites.cons_sub.thresholds.balanced;
  validateCalibration(ok);
  assert.equal(resolveSettings(ok, null, {}, false).sites.cons_sub.threshold, null);
  assert.equal(resolveSettings(ok, null, {}, false).sites.cons_sub.enabled, false);
  const bad3 = JSON.parse(JSON.stringify(cal));
  bad3.default_context = 'c16_l256';
  assert.throws(() => validateCalibration(bad3), (e) => e.field === 'default_context');
});
